// ─── 데이터 파생 (모두 MAP에서 계산) ─────────────────────────────────────
const N = MAP.points.length / 5;
const PT = (i, k) => MAP.points[i * 5 + k];          // 0 x · 1 y · 2 상위 분야 · 3 잎 분야 · 4 연도
const fmt = (n) => M.count(n, { decimals: 0, separator: ',' });
const F = MAP.focus.index, FX = PT(F, 0), FY = PT(F, 1);
const QA = MAP.fields.find((f) => f.label === 'Question Answering');
const YEAR_FROM = 2023;
// source: crates/constellation-core/src/queries/works.rs — year_from 조건은 "(w.year IS NULL OR w.year >= ?)". 연도 미상(0)도 일치로 센다
const MATCH = (i) => PT(i, 4) === 0 || PT(i, 4) >= YEAR_FROM;
const RECENT = (() => { let n = 0; for (let i = 0; i < N; i++) if (MATCH(i)) n++; return n; })();
const CITE = new Map([...MAP.focus.refs.map((i) => [i, 'out']), ...MAP.focus.citedBy.map((i) => [i, 'in'])]);
const CB = (() => {
  let x0 = FX, x1 = FX, y0 = FY, y1 = FY;
  for (const i of CITE.keys()) { x0 = Math.min(x0, PT(i, 0)); x1 = Math.max(x1, PT(i, 0)); y0 = Math.min(y0, PT(i, 1)); y1 = Math.max(y1, PT(i, 1)); }
  return { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, w: x1 - x0, h: y1 - y0 };
})();
